import type { Flashcard } from './flashcardsData';

export const flashcardsLote18: Flashcard[] = [
  { id: "ped-001", front: "Crupe — escore de Westley: classificação?", back: "Estridor (0-2), retração (0-3), entrada de ar (0-2), cianose (0-4), consciência (0-5). ≤ 2 = leve. 3-5 = moderado. ≥ 6 = grave. Tto: dexametasona 0,6mg/kg VO dose única ± adrenalina nebulizada no moderado/grave.", category: "pediatria", tags: ["crupe", "Westley", "airway"] },
  { id: "ped-002", front: "Síndrome nefrótica infantil: quando biopsiar sem tentar corticoide?", back: "< 1 ano, > 12 anos, hematúria macroscópica, HAS, IRA, C3/C4 baixo, FAN+, história familiar. Nesses casos: probabilidade de lesão mínima é baixa — biópsia antes de corticoide.", category: "pediatria", tags: ["nefrótica", "biópsia", "corticoide"] },
  { id: "ped-003", front: "Meningite bacteriana em lactente 1-3 meses: esquema empírico?", back: "Ceftriaxona + ampicilina (cobre Listeria e GBS) + dexametasona 0,15mg/kg 6/6h × 4 dias antes ou com ATB. > 3 meses: ceftriaxona + dexametasona.", category: "pediatria", tags: ["meningite", "ceftriaxona", "ampicilina"] },
  { id: "ped-004", front: "Invaginação intestinal: faixa etária, tríade clínica e tratamento?", back: "6 meses a 3 anos. Tríade: dor cólica paroxística + massa abdominal + fezes em geleia de groselha. US: sinal do alvo. Tto: enema pneumático (85-90% eficaz); falha ou peritonite: cirurgia.", category: "pediatria", tags: ["invaginação", "enema", "cirurgia"] },
  { id: "ped-005", front: "Bronquiolite viral: quais tratamentos NÃO têm evidência?", back: "Sem evidência: salbutamol, corticoide sistêmico, ATB, adrenalina rotineira. Tto suportivo: O₂ se SpO₂ < 92%, hidratação. CNAF: benefício moderado nos graves.", category: "pediatria", tags: ["bronquiolite", "VSR", "evidência"] },
  { id: "ped-006", front: "APGAR: itens e significado de < 4?", back: "Aparência, Pulso, Grimace, Atividade, Respiração (0-2 cada). > 7 = normal. 4-6 = depressão leve. < 4 = grave → reanimação imediata. Avaliar no 1° e 5° minutos.", category: "pediatria", tags: ["APGAR", "neonatal", "reanimação"] },
  { id: "ped-007", front: "Febre sem foco em lactente < 28 dias: conduta?", back: "Internação + hemocultura + urinocultura + PL + ATB empírico (ampicilina + gentamicina). 29-60 dias: estratificar por escore de Rochester. Alto risco: internar.", category: "pediatria", tags: ["febre", "lactente", "sepse"] },
  { id: "ped-008", front: "Síndrome de Reye: causa e por que AAS é contraindicado < 12 anos?", back: "Encefalopatia + disfunção hepática após vírus (influenza, varicela) + AAS. AAS inibe β-oxidação mitocondrial → falência hepática. Sempre evitar AAS em < 12 anos com vírus.", category: "pediatria", tags: ["Reye", "AAS", "vírus"] },
  { id: "ped-009", front: "Dose máxima de paracetamol pediátrico?", back: "10-15 mg/kg/dose a cada 4-6h. Máximo: 75 mg/kg/dia ou 4g/dia (o menor). Intervalo mínimo: 4h. Superdose > 150mg/kg → hepatotoxicidade.", category: "pediatria", tags: ["paracetamol", "dose", "hepatotoxicidade"] },
  { id: "ped-010", front: "Kawasaki incompleto: quando suspeitar?", back: "Febre ≥ 5 dias + < 4 critérios clássicos, especialmente em < 6 meses. Investigar: PCR/VHS + laboratorial + ecocardiograma. Se eco alterado: tratar como Kawasaki completo.", category: "pediatria", tags: ["Kawasaki", "incompleto", "eco"] },
  { id: "ped-011", front: "Puberdade precoce central vs periférica: como diferenciar?", back: "Central: LH pós-GnRH elevado, estradiol/testosterona aumentados. Periférica: LH baixo, sem resposta ao GnRH. Tto central: análogo de GnRH (leuprolide mensal).", category: "pediatria", tags: ["puberdade precoce", "GnRH", "leuprolide"] },
  { id: "ped-012", front: "Epiglotite: por que NÃO examinar a orofaringe antes de garantir VA?", back: "Estimulação orofaríngea → laringoespasmo → obstrução total. IOT em CC com ENT presente + ceftriaxona IV. Sinal do polegar no RX lateral.", category: "pediatria", tags: ["epiglotite", "laringoespasmo", "IOT"] },
  { id: "ped-013", front: "Convulsão febril simples vs complexa: diferença?", back: "Simples: generalizada, < 15 min, 1 episódio/24h, sem déficit pós-ictal. Complexa: focal OU > 15 min OU > 1/24h OU déficit. Complexa: EEG + neuroimagem. Ambas: não indicam antiepiléptico profilático de rotina.", category: "pediatria", tags: ["convulsão febril", "simples", "complexa"] },
  { id: "ped-014", front: "Nomograma de Bhutani: como usar?", back: "Plotar bilirrubina total (mg/dL) × horas de vida. Zona > P95: fototerapia intensiva. Fatores agravantes (prematuridade, hemólise, sepse): abaixam o limiar de intervenção.", category: "pediatria", tags: ["Bhutani", "fototerapia", "bilirrubina"] },
  { id: "ped-015", front: "Anemia ferropênica no lactente: quando rastrear e como tratar?", back: "Screening: hemograma aos 9-12 meses (4 meses se prematuro). Tto: sulfato ferroso 3-5 mg/kg/dia de ferro elementar, 1h antes das refeições, por 3 meses após normalização.", category: "pediatria", tags: ["anemia", "ferro", "lactente"] },
  { id: "ped-016", front: "DNPM aos 12 meses: marcos esperados?", back: "Motor: andar com apoio ou sozinho. Linguagem: 2-3 palavras com sentido (mama/papa específico). Social: aponta para objetos. Red flag: não fica em pé, sem palavras com sentido.", category: "pediatria", tags: ["DNPM", "12 meses", "desenvolvimento"] },
  { id: "ped-017", front: "Fenilcetonúria: janela terapêutica?", back: "Triagem no pezinho 3°-5° dia. Confirmação: Phe > 360 µmol/L. Dieta hipofenilalanina + suplemento iniciado em < 3 semanas → QI normal. Cada semana de atraso = ~1 ponto de QI perdido irreversivelmente.", category: "pediatria", tags: ["PKU", "triagem", "pezinho"] },
  { id: "ped-018", front: "Síndrome de Down: o que rastrear além de cardiopatia?", back: "TSH (nascimento, 6m, 12m, anual), anti-tTG IgA (celíaca ≥ 2 anos), audição (OEA ao nascimento), visão, instabilidade atlantoaxial (RX cervical). Eco neonatal: cardiopatia em 40%.", category: "pediatria", tags: ["Down", "rastreio", "hipotireoidismo"] },
  { id: "ped-019", front: "Coqueluche em < 6 meses: manifestação atípica?", back: "Apneia sem tosse típica + cianose + bradicardia (tríade do lactente). Leucocitose com linfocitose extrema (> 30.000) = mau prognóstico. Tto: azitromicina + UTI neonatal se grave.", category: "pediatria", tags: ["coqueluche", "apneia", "lactente"] },
  { id: "ped-020", front: "Herpes neonatal: quando iniciar aciclovir empiricamente?", back: "Suspeita (vesículas + encefalite + sepse sem foco em RN): aciclovir 20mg/kg IV 8/8h × 14-21 dias SEM aguardar confirmação. Cada hora conta.", category: "pediatria", tags: ["herpes neonatal", "aciclovir", "empírico"] },
  { id: "ped-021", front: "Vacinas ao nascimento: quais e como aplicar?", back: "HepB (IM): primeiras 12-24h. BCG (ID): deltóide direito ao nascimento. Se mãe HBsAg+: IGHB < 12h em sítio oposto à vacina.", category: "pediatria", tags: ["vacinas", "RN", "BCG"] },
  { id: "ped-022", front: "APLV IgE-mediada vs não mediada: como diferenciar?", back: "IgE: imediata (< 2h), urticária/anafilaxia, prick test+. Não-IgE: retardada (> 2h-dias), enterocolite/proctocolite, prick-. Ambas: exclusão + reintrodução.", category: "pediatria", tags: ["APLV", "IgE", "alergia alimentar"] },
  { id: "ped-023", front: "Refluxo em lactente: quando usar IBP?", back: "Não usar em RGE fisiológico (sem repercussão). DRGE (perda de peso, esofagite, apneia): omeprazol 0,5-1mg/kg/dia. IBP em RGE fisiológico: sem benefício + risco de infecções.", category: "pediatria", tags: ["refluxo", "IBP", "DRGE"] },
  { id: "ped-024", front: "Síndrome de Turner: achados e principal complicação CV?", back: "45,X. Baixa estatura + pescoço alado + amenorreia primária. CV: coarctação da aorta (10-20%) e válvula aórtica bicúspide (30%). Eco neonatal obrigatório.", category: "pediatria", tags: ["Turner", "coarctação", "genética"] },
  { id: "ped-025", front: "Estenose hipertrófica do piloro: achados e tratamento?", back: "2-8 semanas, sexo masculino. Vômito em jato não bilioso + fome voraz + massa no epigástrio. Alcalose metabólica hipoclorêmica hipocalêmica. US: músculo > 3-4mm. Tto: piloromiotomia (após correção eletrolítica).", category: "pediatria", tags: ["piloro", "estenose", "alcalose"] },
  { id: "ped-026", front: "Hirschsprung: achado patognomônico e diagnóstico?", back: "Falha de eliminação de mecônio > 48h + distensão abdominal. Retoque retal: saída explosiva. Biópsia retal (padrão-ouro): ausência de células ganglionares. Tto: cirurgia.", category: "pediatria", tags: ["Hirschsprung", "mecônio", "biópsia retal"] },
  { id: "ped-027", front: "Critério de Paradise para adenotonsilectomia?", back: "≥ 7/ano OU ≥ 5 × 2 anos OU ≥ 3 × 3 anos com documentação. Também: SAOS com hipertrofia tonsilar, abscesso periamigdaliano recorrente.", category: "pediatria", tags: ["tonsilectomia", "Paradise", "amigdalite"] },
  { id: "ped-028", front: "Síndrome de West: tríade e tratamento?", back: "Espasmos em flexão (3-12 meses) + hipsarritmia no EEG + regressão do DNPM. Tto: ACTH ou vigabatrina (1ª linha AAP). Etiologia: hipóxia perinatal, esclerose tuberosa, trissomia 21.", category: "pediatria", tags: ["West", "espasmos infantis", "hipsarritmia"] },
  { id: "ped-029", front: "TRO na desidratação leve-moderada: esquema?", back: "SRO 75 mEq Na+/L: 50-100 mL/kg em 2-4h (reidratação). Manutenção: perdas + 10 mL/kg por evacuação líquida. Vômito não contraindica: oferecer 5 mL/kg a cada 1-2 min.", category: "pediatria", tags: ["TRO", "desidratação", "SRO"] },
  { id: "ped-030", front: "LLA infantil: grupo de melhor prognóstico?", back: "1-9 anos, leucócitos < 50.000, B-cell common, sem BCR-ABL, com t(12;21)/ETV6-RUNX1. Sobrevida > 90% com QT por 2-3 anos.", category: "pediatria", tags: ["LLA", "prognóstico", "leucemia"] },
  { id: "ped-031", front: "Dose de adrenalina na anafilaxia em criança?", back: "0,01 mg/kg IM face anterolateral da coxa (solução 1:1000). Máximo: 0,5mg. Repetir a cada 5-15 min. Anti-histamínico e corticoide: adjuvantes, não substituem.", category: "pediatria", tags: ["anafilaxia", "adrenalina", "dose"] },
  { id: "ped-032", front: "Hipoglicemia neonatal: valor e tratamento imediato?", back: "< 45 mg/dL nas primeiras 48h. Assintomático: amamentar + reavaliar em 30 min. Sintomático/refratário: glicose 10% 2mL/kg IV bolus + BIC.", category: "pediatria", tags: ["hipoglicemia", "neonatal", "glicose"] },
  { id: "ped-033", front: "Craniosinostose mais comum e tratamento?", back: "Sagital (escafocefalia): crânio estreito e longo. Coronal: plagiocefalia frontal + deformidade orbitária. Tto: cirurgia craniofacial < 1 ano.", category: "pediatria", tags: ["craniosinostose", "sagital", "cirurgia"] },
  { id: "ped-034", front: "Incompatibilidade ABO: diferença da incompatibilidade Rh?", back: "Mãe O + RN A ou B. Icterícia precoce mas mais leve que Rh. Coombs direto fraco. Fototerapia pelo nomograma. EXT: raramente necessária.", category: "pediatria", tags: ["ABO", "incompatibilidade", "Rh"] },
  { id: "ped-035", front: "Meningite tuberculosa em criança: tratamento?", back: "RIPE × 2 meses → RH × 10 meses (total 12 meses). Dexametasona 0,3-0,4mg/kg/dia × 4 semanas: reduz mortalidade. LCR: linfócitos + glicose baixa + proteína muito alta.", category: "pediatria", tags: ["TB meníngea", "RIPE", "dexametasona"] },
  { id: "ped-036", front: "ITU febril em criança: quando internar?", back: "< 2-3 meses, aspecto tóxico, vômitos, germe resistente, uropatia. ATB: ceftriaxona IV → cefixima VO. DMSA pós-ITU: cicatrizes renais.", category: "pediatria", tags: ["ITU", "internação", "ceftriaxona"] },
  { id: "ped-037", front: "Fibrose cística: gene e diagnóstico?", back: "CFTR (F508del mais comum). Triagem: IRT no pezinho. Diagnóstico: suor (Cl > 60 mEq/L) ou 2 mutações patogênicas. Clinica: íleo meconial + bronquiectasias + insuficiência pancreática.", category: "pediatria", tags: ["fibrose cística", "CFTR", "suor"] },
  { id: "ped-038", front: "Critérios de PIDS/IDSA para internação de PAC pediátrica?", back: "SpO₂ < 90%, desconforto grave, apneia, não tolera VO, falha ambulatorial, < 6 meses com suspeita bacteriana. ATB IV: ceftriaxona.", category: "pediatria", tags: ["PAC", "internação", "critérios"] },
  { id: "ped-039", front: "Maus-tratos em criança: quando suspeitar?", back: "Fraturas em diferentes estágios, padrão incompatível com a história, queimaduras com bordas regulares, hematoma subdural sem TCE grave, lesão em área protegida, história inconsistente. Notificação obrigatória (ECA).", category: "pediatria", tags: ["maus-tratos", "notificação", "ECA"] },
  { id: "ped-040", front: "Varicela em imunocompetente: quando usar aciclovir?", back: "> 12 anos, doença cutânea/pulmonar crônica, corticoide sistêmico crônico, 2° caso domiciliar. Dose: 20mg/kg/dose VO 4x/dia × 5 dias.", category: "pediatria", tags: ["varicela", "aciclovir", "indicações"] },
  { id: "ped-041", front: "Pilha de botão no esôfago: urgência?", back: "Corrente elétrica contínua → necrose por OH⁻ em < 2h. RX tórax imediato (duplo halo). Endoscopia em < 2h. Pilha no estômago: menor risco, monitorar com RX.", category: "pediatria", tags: ["pilha de botão", "urgência", "esôfago"] },
  { id: "ped-042", front: "Atresia biliar: diagnóstico e janela cirúrgica?", back: "Icterícia colestática > 2 semanas + fezes acólicas. US: sem vesícula. Cintilografia: sem excreção. Kasai em < 60 dias → melhor prognóstico. > 90 dias: transplante hepático.", category: "pediatria", tags: ["atresia biliar", "Kasai", "transplante"] },
  { id: "ped-043", front: "Síndrome de Shaken Baby: tríade?", back: "Hematoma subdural bilateral sem trauma + hemorragia retiniana bilateral + encefalopatia. Fraturas metafisárias em bucket-handle + costais posteriores. Notificação obrigatória.", category: "pediatria", tags: ["Shaken Baby", "subdural", "maus-tratos"] },
  { id: "ped-044", front: "Hérnia diafragmática congênita: conduta imediata no RN?", back: "Cianose + abdome escavado + ausência de MV no hemitórax. IOT imediata (NUNCA máscara-ambu). Cirurgia após estabilização. Complicação: hipoplasia pulmonar + HPPN.", category: "pediatria", tags: ["hérnia diafragmática", "IOT", "HPPN"] },
  { id: "ped-045", front: "TDAH em criança: critérios mínimos DSM-5?", back: "≥ 6 sintomas de desatenção e/ou hiperatividade, ≥ 2 ambientes, ≥ 6 meses, início < 12 anos, com prejuízo funcional. Tto: psicoeducação + TCC + metilfenidato (> 6 anos).", category: "pediatria", tags: ["TDAH", "DSM-5", "metilfenidato"] },
  { id: "ped-046", front: "SHU: por que NÃO usar ATB?", back: "STEC (E. coli O157:H7): ATB aumenta liberação de toxina Shiga → maior risco de SHU. Não usar antidiarreicos. Tto: suporte + diálise.", category: "pediatria", tags: ["SHU", "STEC", "contraindicação"] },
  { id: "ped-047", front: "Hipospádia: por que não circuncidar antes da cirurgia?", back: "Prepúcio é usado como enxerto na uretroplastia. Cirurgia eletiva: 6-18 meses. Hipospádia grave: investigar DDS (cariótipo + 17-OH-progesterona).", category: "pediatria", tags: ["hipospádia", "circuncisão", "uretroplastia"] },
  { id: "ped-048", front: "APLV: manejo dietético?", back: "Fórmula extensamente hidrolisada (1ª linha) ou aminoacídica (casos graves). Excluir leite e derivados 2-4 semanas. Reintrodução aos 6-12 meses para confirmar tolerância.", category: "pediatria", tags: ["APLV", "fórmula hidrolisada", "exclusão"] },
  { id: "ped-049", front: "Sepse neonatal tardia: agente e tratamento?", back: "Staphylococcus coagulase-negativo em prematuros (PICC/cateter). Tto: vancomicina + aminoglicosídeo. Remover cateter se candidemia.", category: "pediatria", tags: ["sepse tardia", "PICC", "vancomicina"] },
  { id: "ped-050", front: "Síndrome de West vs Dravet: o que EVITAR no Dravet?", back: "Dravet (SCN1A): perda de função de canais de Na+. EVITAR: carbamazepina, fenitoína, lamotrigina (pioram). Usar: valproato + clobazam ± canabidiol.", category: "pediatria", tags: ["Dravet", "SCN1A", "contraindicação"] },
  { id: "ped-051", front: "Hemangioma infantil: quando usar propranolol?", back: "Periorbital (ambliopia), nasal (distorção), ulcerado, comprometendo VA. Dose: 1-3mg/kg/dia × 6 meses. Monitorar glicemia e FC.", category: "pediatria", tags: ["hemangioma", "propranolol", "indicações"] },
  { id: "ped-052", front: "Crise álgica vs síndrome torácica aguda na falciforme?", back: "Crise álgica: vasooclusão óssea, RX sem infiltrado. STA: febre + sintomas respiratórios + infiltrado novo + queda de Hb. STA: O₂ + ATB + exsanguinotransfusão se grave.", category: "pediatria", tags: ["falciforme", "STA", "exsanguinotransfusão"] },
  { id: "ped-053", front: "Atresia de esôfago: diagnóstico pós-natal?", back: "Sialorreia + cianose na 1ª mamada + cateter não passa. RX: sonda enrolada no mediastino. Tipo C (mais comum): bolsa proximal cega + fístula traqueoesofágica distal. Cirurgia imediata.", category: "pediatria", tags: ["atresia esôfago", "cateter", "fístula"] },
  { id: "ped-054", front: "DDS (distúrbio do desenvolvimento sexual): urgência no RN?", back: "Genitália ambígua = emergência. HAC (21-OH): crise adrenal com hiponatremia + hipercalemia fatal. Dosar urgente: 17-OH-progesterona + eletrólitos + cortisol. Não revelar sexo antes da investigação.", category: "pediatria", tags: ["DDS", "HAC", "crise adrenal"] },
  { id: "ped-055", front: "Hipotireoidismo congênito: urgência do tratamento?", back: "TSH alto no pezinho → confirmar com T4 livre. Levotiroxina 10-15 mcg/kg/dia em < 2 semanas. Cada semana de atraso = ~1 ponto de QI perdido irreversivelmente.", category: "pediatria", tags: ["hipotireoidismo congênito", "levotiroxina", "urgência"] },
  { id: "ped-056", front: "Crise asmática grave em criança: papel do sulfato de magnésio?", back: "MgSO₄ 40-50mg/kg IV em 20 min (máx 2g) se sem resposta ao salbutamol + ipratrópio + corticoide. Broncodilatação por bloqueio de Ca²⁺. Efeito em 15-20 min.", category: "pediatria", tags: ["asma grave", "magnésio", "broncodilatação"] },
  { id: "ped-057", front: "Choro excessivo: diagnóstico de exclusão antes de cólica?", back: "Excluir: OMA, hérnia encarcerada, APLV, DRGE, tourniquet syndrome, maus-tratos, invaginação. Cólica = diagnóstico de exclusão.", category: "pediatria", tags: ["choro excessivo", "cólica", "diagnóstico diferencial"] },
  { id: "ped-058", front: "Retinoblastoma: rastreio em familiares?", back: "RB hereditário (RB1 germline): fundo de olho sob anestesia a cada 3-4 semanas no 1° ano. Teste genético para RB1. Enucleação em doença avançada.", category: "pediatria", tags: ["retinoblastoma", "RB1", "rastreio"] },
  { id: "ped-059", front: "Síndrome de Angelman: causa e fenótipo?", back: "Deleção ou mutação UBE3A materno (15q11). Atraso grave, sem fala, convulsões, ataxia, comportamento alegre com riso fácil. Imprinting: mesmo locus que Prader-Willi (paterno).", category: "pediatria", tags: ["Angelman", "UBE3A", "imprinting"] },
  { id: "ped-060", front: "Gastrossquise vs onfalocele: qual tem maior urgência?", back: "Gastrossquise: vísceras expostas sem saco → peritonite + isquemia. Cobrir com SF morno + plástico + cirurgia urgente. Onfalocele: saco íntegro → investigar cromossomopatia + cirurgia programada.", category: "pediatria", tags: ["gastrossquise", "onfalocele", "urgência"] },
  { id: "ped-061", front: "Síndrome de Pierre Robin: urgência neonatal?", back: "Micrognatia + glossoptose + fenda palatina. Glossoptose → obstrução VA → cianose. Posição prona melhora. Tto: tubo nasofaríngeo + distração mandibular.", category: "pediatria", tags: ["Pierre Robin", "glossoptose", "VA"] },
  { id: "ped-062", front: "Fibrose cística: gene e triagem neonatal?", back: "CFTR (F508del). IRT no pezinho. Confirmação: suor (Cl > 60 mEq/L). Manifestações: íleo meconial, bronquiectasias, insuficiência pancreática exócrina, infertilidade masculina.", category: "pediatria", tags: ["fibrose cística", "CFTR", "IRT"] },
  { id: "ped-063", front: "Abuso sexual em criança: coleta forense e janela de tempo?", back: "< 72h: swabs vaginal + anal + oral + coleta de roupas. > 72h: exame físico + sorologias (HIV, HCV, VDRL). Notificação: Conselho Tutelar obrigatória.", category: "pediatria", tags: ["abuso sexual", "forense", "notificação"] },
  { id: "ped-064", front: "Síndrome de Kasabach-Merritt: como tratar?", back: "Hemangioma gigante + plaquetopenia + hipofibrinogenemia. Tto: vincristina IV ou sirolimus VO (não propranolol). Alta mortalidade sem tratamento.", category: "pediatria", tags: ["Kasabach-Merritt", "hemangioma", "trombocitopenia"] },
  { id: "ped-065", front: "Paralisia cerebral: tipos e causas mais comuns?", back: "Espástica (70-80%): lesão NMS. Discinética: gânglios da base (kernicterus/hipóxia). Atáxica: cerebelo. Causas: hipóxia perinatal (20%), prematuridade (28%).", category: "pediatria", tags: ["paralisia cerebral", "espástica", "hipóxia"] },
  { id: "ped-066", front: "Síndrome de abstinência neonatal (NAS): tratamento?", back: "Finnegan > 8: morfina VO. Não farmacológico: swaddling, sucção não nutritiva, ambiente calmo. Alta: após redução progressiva sem recidiva.", category: "pediatria", tags: ["NAS", "opioides", "Finnegan"] },
  { id: "ped-067", front: "Hepatite B no RN de mãe HBsAg+: profilaxia?", back: "IGHB < 12h + HepB em sítios diferentes. Completar esquema aos 1, 2 e 6 meses. Checar HBsAg e anti-HBs aos 9-18 meses para confirmar proteção.", category: "pediatria", tags: ["hepatite B", "RN", "IGHB"] },
  { id: "ped-068", front: "Íleo meconial: associação e tratamento inicial?", back: "80% com fibrose cística (CFTR). Sinal de vidro moído na FID (RX). Enema de contraste hidrosolúvel (Gastrografin): diagnóstico + terapêutico. Cirurgia se falhar.", category: "pediatria", tags: ["íleo meconial", "fibrose cística", "enema"] },
  { id: "ped-069", front: "Prematuridade extrema: principais complicações?", back: "SDR (deficiência de surfactante), HIV (hemorragia intraventricular), leucomalácia, enterocolite necrosante, ROP, DPC, sepse. Tudo inversamente proporcional à IG.", category: "pediatria", tags: ["prematuridade", "SDR", "complicações"] },
  { id: "ped-070", front: "Diagnóstico de DM tipo 1 em criança: achados?", back: "Início agudo (poliúria, polidipsia, perda de peso), cetoacidose em 25-40% dos casos novos, anticorpos (anti-GAD, anti-IA2, anti-insulina). Tto: insulina basal-bolus.", category: "pediatria", tags: ["DM1", "criança", "CAD"] },
  { id: "ped-071", front: "Teste do reflexo vermelho ausente no RN: urgência?", back: "Ausência ou assimetria → oftalmologista urgente. Causas: catarata congênita (cirurgia em < 6-8 semanas para evitar ambliopia), retinoblastoma (emergência oncológica). Rastrear ao nascimento.", category: "pediatria", tags: ["reflexo vermelho", "catarata", "retinoblastoma"] },
  { id: "ped-072", front: "Infecção do trato urinário no lactente: por que pode não ter disúria?", back: "Lactentes expressam ITU com febre sem foco + choro + vômito + recusa alimentar. Disúria só aparece quando a criança já comunica (> 2 anos). Urinocultura por punção suprapúbica ou cateterismo em < 2 anos.", category: "pediatria", tags: ["ITU", "lactente", "febre sem foco"] },
  { id: "ped-073", front: "Síndrome de Lennox-Gastaut: o que a difere de West?", back: "Lennox: > 2 anos, drop attacks + ausência atípica + spike-wave lento (< 2,5Hz) + déficit cognitivo. West: 3-12 meses, espasmos + hipsarritmia. Ambas refratárias; Lennox: ainda mais difícil de tratar.", category: "pediatria", tags: ["Lennox-Gastaut", "West", "epilepsia refratária"] },
  { id: "ped-074", front: "Tuberculose latente em criança: quando tratar?", back: "PPD ≥ 5mm em imunossuprimido ou contato íntimo de TB ativa. ≥ 10mm em imunocompetente. Tto: isoniazida 10mg/kg/dia × 9 meses. Antes: RX tórax + excluir TB ativa.", category: "pediatria", tags: ["TB latente", "isoniazida", "PPD"] },
  { id: "ped-075", front: "Apneia em lactente: causa mais comum e tratamento?", back: "DRGE (mais comum) + anemia + infecção (RSV, coqueluche). Apneia do prematuro: cafeína 20mg/kg IV/VO ataque + 5mg/kg/dia manutenção.", category: "pediatria", tags: ["apneia", "lactente", "cafeína"] },
  { id: "ped-076", front: "Síndrome de CHARGE: componentes e urgência?", back: "Coloboma, Heart defects, Atresia de coana, Retardo, Genitais, Ears (surdez). CHD7. Atresia de coana bilateral: RN é respirador nasal obrigatório → urgência respiratória. Sonda nasal/Guedel até cirurgia.", category: "pediatria", tags: ["CHARGE", "coana", "CHD7"] },
  { id: "ped-077", front: "Tumor de Wilms: faixa etária e apresentação?", back: "Pico 3-5 anos. Massa abdominal indolor. HAS (compressão arterial renal). US + TC. Sobrevida > 90% em estádio I. Não comprimir a massa no exame (risco de ruptura + disseminação).", category: "pediatria", tags: ["Wilms", "nefroblastoma", "HAS"] },
  { id: "ped-078", front: "Hemorragia intraventricular do prematuro: classificação de Papile?", back: "Grau I: germinativo. Grau II: intraventricular sem dilatação. Grau III: intraventricular com dilatação. Grau IV: intraparenquimatosa. Grau III-IV: risco de hidrocefalia pós-hemorrágica e PC.", category: "pediatria", tags: ["HIV", "Papile", "prematuro"] },
  { id: "ped-079", front: "Nutrição parenteral em prematuro: quando iniciar?", back: "Aminoácidos: nas primeiras horas de vida (2-3g/kg/dia) para evitar catabolismo. Glicose: 4-6mg/kg/min. Lipídeo: D1-2, de 1 até 3,5g/kg/dia. Meta proteica: 3-4g/kg/dia.", category: "pediatria", tags: ["nutrição parenteral", "prematuro", "aminoácidos"] },
  { id: "ped-080", front: "Fenilcetonúria: qual o defeito metabólico?", back: "Deficiência de PAH (fenilalanina hidroxilase): Phe não convertida em tirosina → neurotoxicidade. Sem tratamento: DI profunda + convulsões + hipopigmentação.", category: "pediatria", tags: ["PKU", "PAH", "fenilalanina"] },
  { id: "ped-081", front: "Sifilis congênita: quando tratar o RN?", back: "RN de mãe com VDRL reagente: tratar se mãe sem tratamento adequado OU tratamento < 30 dias antes do parto OU sem documentação. Tratamento: penicilina G cristalina IV × 10 dias.", category: "pediatria", tags: ["sífilis congênita", "penicilina", "RN"] },
  { id: "ped-082", front: "Síndrome de Beckwith-Wiedemann: achados e vigilância oncológica?", back: "Macrossomia + macroglossia + onfalocele + hipoglicemia neonatal grave. Risco: tumor de Wilms + hepatoblastoma. US abdominal a cada 3 meses até 8 anos.", category: "pediatria", tags: ["Beckwith-Wiedemann", "Wilms", "hipoglicemia"] },
  { id: "ped-083", front: "Asma em lactente: como diagnosticar sem espirometria?", back: "Índice preditivo de asma (IPA): > 3 episódios/ano + critério maior (familiar com asma, atopia) ou 2 menores (eosinofilia, rinite, sibilância sem resfriado). IPA+: tratar como asma.", category: "pediatria", tags: ["asma", "lactente", "IPA"] },
  { id: "ped-084", front: "Crise álgica na doença falciforme: manejo inicial?", back: "Hidratação IV (1,5× manutenção) + analgesia escalonada: AINEs → tramadol → morfina titulada. O₂ somente se SpO₂ < 95%. Aquecimento local. Afastar precipitantes.", category: "pediatria", tags: ["falciforme", "crise álgica", "analgesia"] },
  { id: "ped-085", front: "Hérnia inguinal indireta em lactente: urgência?", back: "Principal causa de obstrução intestinal em lactentes. Sinal de encarceramento: tumor inguinoescrotal irredutível + choro + vômito bilioso. Redução manual se < 4h e sem sinais de estrangulamento. Cirurgia urgente se estrangulado.", category: "pediatria", tags: ["hérnia inguinal", "encarceramento", "cirurgia"] },
  { id: "ped-086", front: "Gastroenterite bacteriana em criança: quando dar ATB?", back: "Shigella (cipro), febre tifoide (azitro/ceftriaxona), cólera (azitro), Campylobacter em imunossuprimido. NÃO: Salmonella não typhi (prolonga portador), STEC (risco SHU).", category: "pediatria", tags: ["gastroenterite", "ATB", "indicações"] },
  { id: "ped-087", front: "Criança de 2 anos com febre + petéquias: conduta?", back: "EMERGÊNCIA: meningococcemia até prova contrária. Ceftriaxona IV imediato sem aguardar PL. Petéquias acima dos mamilos com cuff negativo podem ser benignas, mas não reduzem a urgência sem avaliação completa.", category: "pediatria", tags: ["petéquias", "meningococcemia", "urgência"] },
  { id: "ped-088", front: "AIJ sistêmica (Still da criança): diferença da oligoarticular?", back: "Sistêmica: febre quotidiana + rash salmon evanescente + artrite + ferritina muito elevada + serosite. Complicação: hemofagocitose (SHM). Tto: anakinra (anti-IL1) ou tocilizumabe. Oligoarticular: FAN+ + uveíte crônica assintomática.", category: "pediatria", tags: ["AIJ sistêmica", "Still", "hemofagocitose"] },
  { id: "ped-089", front: "Púrpura de Henoch-Schönlein em criança: tríade e prognóstico?", back: "Púrpura não trombocitopênica (MMII) + artrite + dor abdominal ± nefrite. Depósito de IgA. Autolimitada em 90% das crianças. Nefrite: monitorar proteinúria; se grave, imunossupressão.", category: "pediatria", tags: ["Henoch-Schönlein", "IgA", "púrpura"] },
  { id: "ped-090", front: "Doença de Kawasaki: tratamento e risco principal?", back: "IVIG 2g/kg dose única IV + AAS. Risco: aneurisma coronariano (até 25% sem tratamento, 4% com IVIG). Ecocardiograma: D0, D15 e D60. Refratário: 2ª dose de IVIG ou infliximabe.", category: "pediatria", tags: ["Kawasaki", "IVIG", "aneurisma coronariano"] },
  { id: "ped-091", front: "Sepse neonatal precoce (< 72h): agentes e esquema?", back: "GBS (Streptococcus agalactiae) + E. coli + Listeria. Tto: ampicilina + gentamicina. Diferencial de sepse tardia: S. epidermidis + Candida em prematuros com cateter.", category: "pediatria", tags: ["sepse precoce", "GBS", "ampicilina"] },
  { id: "ped-092", front: "Estenose de piloro: como corrigir o distúrbio metabólico antes da cirurgia?", back: "Alcalose metabólica hipoclorêmica: reposição de NaCl 0,9% + KCl (KVO até Cl sérico normal). NUNCA operar com distúrbio grave: risco de apneia pós-operatória por alcalose.", category: "pediatria", tags: ["piloro", "alcalose metabólica", "pré-operatório"] },
  { id: "ped-093", front: "Toxoplasmose congênita: tratamento e duração?", back: "Pirimetamina + sulfadiazina + ácido folínico × 12 meses. Hidrocefalia: DVP. Coriorretinite: tratar localmente também. Rastreio: oftalmológico + neurológico + auditivo.", category: "pediatria", tags: ["toxoplasmose", "pirimetamina", "12 meses"] },
  { id: "ped-094", front: "Síndrome de Turner: como confirmar e tratar baixa estatura?", back: "Cariótipo (45,X ou mosaico). GH recombinante: indicado mesmo sem deficiência documentada (aumenta estatura final ~7cm). Estrogênio: iniciar puberdade induzida aos 11-12 anos.", category: "pediatria", tags: ["Turner", "GH", "estatura"] },
  { id: "ped-095", front: "Leucemia mielóide aguda M3 em criança: emergência associada?", back: "CIVD (coagulação intravascular disseminada): fibrinogênio baixo + plaquetas baixas + D-dímero alto. Emergência ao diagnóstico. ATRA + ATO iniciar imediatamente (diferenciam os blastos e resolvem a CIVD).", category: "pediatria", tags: ["LMA M3", "CIVD", "ATRA"] },
  { id: "ped-096", front: "Hérnia diafragmática: por que não usar máscara-ambu?", back: "Ventilação com máscara insufla o estômago (no tórax) → compressão adicional do pulmão contralateral. IOT imediata com tubo de pequeno calibre. SNG para descomprimir estômago.", category: "pediatria", tags: ["hérnia diafragmática", "máscara-ambu", "IOT"] },
  { id: "ped-097", front: "Talassemia beta major (Cooley): tratamento e complicação?", back: "Transfusão crônica (meta Hb > 9-10g/dL) + quelação de ferro (deferasirox). Complicação: hemocromatose transfusional (coração, fígado, endócrino). Transplante de MO: único tratamento curativo.", category: "pediatria", tags: ["talassemia", "quelação", "TMO"] },
  { id: "ped-098", front: "Doença de Perthes vs SCFE: faixa etária e conduta?", back: "Perthes (4-8 anos): NAV idiopática. Tto: contenção. SCFE (10-16 anos, obeso): deslizamento epifisário. Cirurgia urgente sem manipulação (risco de NAV). RX: sinal de Klein.", category: "pediatria", tags: ["Perthes", "SCFE", "quadril"] },
  { id: "ped-099", front: "Puberdade precoce em menino: por que mais preocupante que em menina?", back: "Em meninas < 8 anos: idiopática em 80%. Em meninos < 9 anos: causa orgânica (tumor SNC, hamartoma hipotalâmico) em > 50%. RM hipofisária/hipotalâmica obrigatória em todo menino com PP central.", category: "pediatria", tags: ["puberdade precoce", "menino", "SNC"] },
  { id: "ped-100", front: "Enurese noturna primária: tratamento mais eficaz a longo prazo?", back: "Alarme de enurese: 75% de cura com adesão. Superior à desmopressina (alta taxa de recidiva ao suspender). Desmopressina: efeito rápido para situações pontuais.", category: "pediatria", tags: ["enurese", "alarme", "desmopressina"] },
  { id: "ped-101", front: "Intoxicação por organofosforado em criança: diagnóstico e tratamento?", back: "SLUDGE (salivação, lacrimejamento, urina, diarreia, GI, êmese) + bradicardia + miose. Tto: atropina 0,05mg/kg IV repetida até broncodilatação + pralidoxima 25mg/kg IV.", category: "pediatria", tags: ["organofosforado", "atropina", "SLUDGE"] },
  { id: "ped-102", front: "Otite média aguda em criança: quando NÃO prescrever ATB?", back: "≥ 2 anos + OMA unilateral leve + otalgia < 48h: watchful waiting aceitável. ATB: < 2 anos, bilateral, perfuração espontânea, otalgia grave, febre > 39°C. ATB: amoxicilina 80-90mg/kg/dia.", category: "pediatria", tags: ["OMA", "watchful waiting", "amoxicilina"] },
  { id: "ped-103", front: "Quais os tumores cerebrais mais comuns em crianças?", back: "Fossa posterior (3-10 anos): astrocitoma cerebelar (mais comum), meduloblastoma (mais maligno + radiosensível), ependimoma. < 2 anos e > 10 anos: supratentoriais predominam.", category: "pediatria", tags: ["tumor cerebral", "fossa posterior", "meduloblastoma"] },
  { id: "ped-104", front: "Síndrome nefrótica em criança 4 anos sem red flags: conduta?", back: "Prednisona 2mg/kg/dia (máx 80mg) × 4-6 semanas sem biópsia prévia. Lesão mínima em > 80%. Resposta = diagnóstico presuntivo. Biópsia: não resposta, recorrências frequentes.", category: "pediatria", tags: ["nefrótica", "prednisona", "lesão mínima"] },
  { id: "ped-105", front: "Púrpura trombocitopênica imune (PTI) aguda em criança: manejo?", back: "PTI aguda (pós-viral, plaquetas < 20.000): observação se assintomático (cura espontânea em 80-90%). Tto se sangramento significativo: IVIG 1g/kg/dia × 2 dias OU prednisona. NÃO esplenectomia na fase aguda.", category: "pediatria", tags: ["PTI", "IVIG", "plaquetopenia"] },
  { id: "ped-106", front: "Sepse por meningococo em criança: qual a antibioticoprofilaxia para contatos?", back: "Rifampicina 10mg/kg (máx 600mg) 12/12h × 2 dias (1ª linha). Alternativa: ciprofloxacino dose única (adultos) ou ceftriaxona IM dose única. Iniciar em < 24h do diagnóstico do caso índice.", category: "pediatria", tags: ["meningococo", "profilaxia", "rifampicina"] },
  { id: "ped-107", front: "SMSL: fatores de risco e prevenção?", back: "Decúbito ventral, superfície mole, tabagismo passivo, co-sleeping em sofá, cobertor na face. Protetores: decúbito dorsal exclusivo até 1 ano, amamentação, chupeta, quarto com os pais (cama separada).", category: "pediatria", tags: ["SMSL", "prevenção", "decúbito"] },
  { id: "ped-108", front: "RN filho de mãe com tuberculose ativa: conduta?", back: "Separar até mãe ter ≥ 2 semanas de RIPE + baciloscopia negativa. NÃO BCG (risco BCGite em infectado). Isoniazida 10mg/kg/dia × 6 meses. Após: PPD e BCG se negativo.", category: "pediatria", tags: ["TB", "RN", "isoniazida"] },
  { id: "ped-109", front: "Criança de 5 anos com artrite oligoarticular + uveíte: diagnóstico?", back: "AIJ oligoarticular (menina pequena, FAN+). Uveíte anterior crônica assintomática em 20-30% → risco de cegueira. Rastreio: lâmpada de fenda a cada 3 meses. MTX + anti-TNF: refratário.", category: "pediatria", tags: ["AIJ", "uveíte", "rastreio"] },
  { id: "ped-110", front: "Celulite periorbitária vs orbitária: como diferenciar?", back: "Periorbitária (pré-septal): sem proptose, sem oftalmoplegia, sem dor ao mover o olho. ATB oral. Orbitária (pós-septal): proptose + oftalmoplegia + dor ao mover + febre. TC urgente + ATB IV + avaliação cirúrgica.", category: "pediatria", tags: ["celulite orbitária", "proptose", "TC"] },
  { id: "ped-111", front: "Doença de Hirschsprung de segmento curto vs longo: diferença?", back: "Curto (reto e sigmóide): mais comum (80%), diagnóstico tardio, constipação crônica desde o nascimento. Longo: intestino delgado envolvido, quadro grave desde o berçário, nutrição parenteral. Biópsia múltipla nível-por-nível para mapear extensão.", category: "pediatria", tags: ["Hirschsprung", "segmento", "extensão"] },
  { id: "ped-112", front: "Síndrome de Down: cardiopatia mais comum?", back: "Canal atrioventricular completo (DSAV) em 40-50% dos com cardiopatia. Cirurgia em < 6 meses (antes da hipertensão pulmonar irreversível). Eco neonatal obrigatório em todos.", category: "pediatria", tags: ["Down", "DSAV", "cardiopatia"] },
  { id: "ped-113", front: "Recém-nascido com fontanela abaulada + febre: hipóteses?", back: "HIC: meningite bacteriana (urgência), hidrocefalia aguda, HSA, hematoma subdural. Conduta: PL (se sem HIC grave) + hemocultura + ceftriaxona + dexametasona empírico.", category: "pediatria", tags: ["fontanela", "HIC", "meningite"] },
  { id: "ped-114", front: "Síndrome de Kasabach-Merritt: como diferenciar de hemangioma benigno?", back: "Hemangioma gigante + plaquetopenia + hipofibrinogenemia (CID localizada). Hemangioma infantil benigno: não consome plaquetas. Tto Kasabach: vincristina IV ou sirolimus (não propranolol).", category: "pediatria", tags: ["Kasabach-Merritt", "hemangioma", "diferencial"] },
  { id: "ped-115", front: "Toxoplasmose gestacional: tratamento materno?", back: "< 18 semanas: espiramicina (reduz transmissão, não trata feto). ≥ 18 semanas ou infecção fetal confirmada (amniocentese): pirimetamina + sulfadiazina + ácido folínico. Espiramicina: não atravessa placenta.", category: "pediatria", tags: ["toxoplasmose", "espiramicina", "gestação"] },
  { id: "ped-116", front: "Diagnóstico de RVU: qual o exame padrão-ouro?", back: "Cistouretrograma miccional (CUGM): mostra o refluxo em tempo real durante a micção. DMSA: detecta cicatrizes renais. US renal: detecta hidroureteronefrose mas não gradua o RVU.", category: "pediatria", tags: ["RVU", "CUGM", "DMSA"] },
  { id: "ped-117", front: "Criança de 3 meses com cianose ao mamar + sibilância unilateral: diagnóstico?", back: "Anel vascular (artéria subclávia aberrante, arco aórtico duplo): compressão da traqueia e do esôfago. Diagnóstico: TC tórax com contraste (angio-TC) ou RX com contraste esofágico (impressão esofágica). Cirurgia eletiva.", category: "pediatria", tags: ["anel vascular", "cianose", "sibilância"] },
  { id: "reuma-001", front: "LES — critérios EULAR/ACR 2019: como pontuar?", back: "Critério de entrada obrigatório: FAN ≥ 1:80. Depois: 10 domínios ponderados (constitucional, hematológico, neuropsiquiátrico, renal, pele, serosites, articular, complemento, antifosfolipídios, anticorpos específicos). ≥ 10 pontos = LES. Especificidade 97%.", category: "reumatologia", tags: ["LES", "EULAR", "classificação"] },
  { id: "reuma-002", front: "Qual anticorpo confirma LES com alta especificidade?", back: "Anti-Sm (Smith): especificidade > 95%. Sensibilidade 25-30%. Se positivo: praticamente confirma LES. Anti-dsDNA: alta especificidade + correlação com atividade e nefrite.", category: "reumatologia", tags: ["LES", "anti-Sm", "especificidade"] },
  { id: "reuma-003", front: "Nefrite lúpica: o que define a conduta em cada classe?", back: "Classe I-II: IECA/BRA. Classe III-IV (proliferativa): metilprednisolona pulso + MMF ou ciclofosfamida → manutenção MMF + HCQ. Classe V: IECA/BRA ± imunossupressor. Classe VI: transplante.", category: "reumatologia", tags: ["nefrite lúpica", "ISN/RPS", "MMF"] },
  { id: "reuma-004", front: "Sjögren: complicações extraglandulares mais graves?", back: "Linfoma B de zona marginal (MALT) 5-10×. Vasculite crioglobulinêmica (HCV): púrpura + neuropatia + GN. DPI. Monitorar: proteínas totais + crioglobulinas + hemograma anual.", category: "reumatologia", tags: ["Sjögren", "linfoma", "crioglobulinemia"] },
  { id: "reuma-005", front: "Esclerodermia: anticorpos e fenótipos?", back: "Anti-centrômero: lcSSc (CREST, melhor prognóstico, HAP). Anti-Scl-70 (topoisomerase I): dcSSc + DPI grave. Anti-RNA pol III: dcSSc + crise renal esclerodérmica. Anti-U1RNP: overlap.", category: "reumatologia", tags: ["esclerodermia", "anticorpos", "fenótipo"] },
  { id: "reuma-006", front: "Crise renal esclerodérmica: por que manter IECA mesmo com Cr elevada?", back: "Anti-RNA pol III → vasoconstricção angiotensina-dependente nas arteríolas renais → IRA. IECA (captopril): bloqueia a patogênese. NUNCA suspender pela Cr — está tratando a causa. Diálise temporária possível mas rim pode recuperar.", category: "reumatologia", tags: ["CRE", "captopril", "IRA"] },
  { id: "reuma-007", front: "Dermatomiosite vs polimiosite: diferença histológica e anticorpos?", back: "DM: inflamação perimisial + perivascular (CD4+). Manifestações cutâneas obrigatórias. PM: endomisial (CD8+). Anti-TIF1γ: DM + CA sólido. Anti-MDA5: DM amiopática + DPI grave. Anti-Jo1: síndrome antisintetase (miosite + DPI + artrite).", category: "reumatologia", tags: ["DM", "PM", "histologia"] },
  { id: "reuma-008", front: "Síndrome antisintetase: tríade e anticorpo mais comum?", back: "Miosite + DPI + artrite. Anti-Jo1: mais comum (anti-histidil tRNA sintetase). Raynaud + mãos de mecânico também. DPI pode preceder a miosite. Tratamento: corticoide + azatioprina ou MMF.", category: "reumatologia", tags: ["antisintetase", "anti-Jo1", "DPI"] },
  { id: "reuma-009", front: "GPA vs PAM: diferença clínica e ANCA?", back: "GPA: vias aéreas superiores (sinusite granulomatosa) + pulmões (nódulos cavitados) + rins (GNRP). c-ANCA/anti-PR3 em 90%. PAM: sem granulomas, sem vias aéreas superiores. p-ANCA/anti-MPO. Tratamento: rituximabe ou ciclofosfamida + metilprednisolona.", category: "reumatologia", tags: ["GPA", "PAM", "ANCA"] },
  { id: "reuma-010", front: "Espondiloartropatias soronegativas: características em comum?", back: "EA, APs, artrite reativa, artropatia enteropática. HLA-B27 (variável), entesite (inserção de tendão no osso), artrite assimétrica, uveíte anterior, envolvimento axial. Sem FR e anti-CCP.", category: "reumatologia", tags: ["espondiloartropatias", "HLA-B27", "entesite"] },
  { id: "reuma-011", front: "Gota: por que NÃO iniciar alopurinol na crise aguda?", back: "Flutuação dos níveis de urato → precipitação de novos cristais → piora ou nova crise. Iniciar: 2-4 semanas após resolução + colchicina profilática 3-6 meses durante titulação.", category: "reumatologia", tags: ["gota", "alopurinol", "crise aguda"] },
  { id: "reuma-012", front: "AR: qual a meta do treat-to-target?", back: "Remissão (DAS28 < 2,6) ou baixa atividade (DAS28 < 3,2). Reavaliar a cada 1-3 meses. Sem melhora em 3 meses ou meta não atingida em 6 meses: mudar terapia.", category: "reumatologia", tags: ["AR", "treat-to-target", "DAS28"] },
  { id: "reuma-013", front: "Febre reumática: duração da profilaxia secundária?", back: "Com cardite + lesão valvar residual: até 40 anos ou toda a vida. Sem cardite: 5 anos ou até 21 anos. Com cardite sem lesão residual: 10 anos ou 21 anos. Penicilina G benzatina 1,2 MUI IM a cada 21 dias.", category: "reumatologia", tags: ["febre reumática", "profilaxia", "penicilina"] },
  { id: "reuma-014", front: "EGPA (Churg-Strauss): tríade e ANCA?", back: "Asma grave + eosinofilia > 10% + vasculite de pequenos vasos. p-ANCA/anti-MPO em 40-60% (não universal). Principal causa de morte: miocardite eosinofílica. Refratário: mepolizumabe (anti-IL5).", category: "reumatologia", tags: ["EGPA", "Churg-Strauss", "eosinofilia"] },
  { id: "reuma-015", front: "Arterite de Takayasu: vasos e diagnóstico?", back: "Aorta + grandes ramos. Mulher jovem + assimetria de pulso/PA + sopros vasculares. Angio-TC/RM: espessamento e estenose aórtica. Tto: prednisona + MTX ou azatioprina. Tocilizumabe: refratário.", category: "reumatologia", tags: ["Takayasu", "grandes vasos", "angio-TC"] },
  { id: "reuma-016", front: "CAPS (SAF catastrófico): tratamento urgente?", back: "Tromboses em ≥ 3 órgãos em ≤ 1 semana + anticorpos antifosfolipídios. Mortalidade 50%. Triple therapy: heparina plena + corticoide IV + IVIG ou plasmaférese. Rituximabe: refratário.", category: "reumatologia", tags: ["CAPS", "SAF", "triple therapy"] },
  { id: "reuma-017", front: "OA vs AR no exame físico: diferenças?", back: "OA: IFD/IFP (Heberden/Bouchard) + joelhos/quadril + rigidez < 30 min + sem sinovite ativa. AR: MCF + punhos + simétrica + sinovite ativa + rigidez > 1h + deformidades.", category: "reumatologia", tags: ["OA", "AR", "diferencial clínico"] },
  { id: "reuma-018", front: "Anti-TNF: triagem obrigatória antes do uso?", back: "TB latente (PPD/IGRA), HBV (HBsAg + anti-HBc + anti-HBs), HIV, vacinação atualizada. IC com FE < 50%: contraindicação relativa. Desmielinização (EM): contraindicado.", category: "reumatologia", tags: ["anti-TNF", "triagem", "TB"] },
  { id: "reuma-019", front: "Pseudo-gota (CPPD): cristais, articulação e tratamento?", back: "Cristais de pirofosfato de cálcio: birrefringência positiva fraca, retangulares. Articulação: joelho (menisco calcificado no RX). Precipitantes: hiperparatireoidismo, hemocromatose, hipomagnesemia. Tratamento: igual à gota (AINE, colchicina, corticoide).", category: "reumatologia", tags: ["CPPD", "pseudo-gota", "condrocalcinose"] },
  { id: "reuma-020", front: "LES: tratamento base obrigatório para todos os pacientes?", back: "Hidroxicloroquina (HCQ) 5mg/kg/dia: reduz flares, mortalidade, trombose, dano cumulativo. Fundo de olho anual após 5 anos (maculopatia). Protetor solar SPF 30+ (fotossensibilidade universal).", category: "reumatologia", tags: ["LES", "HCQ", "base"] },
  { id: "reuma-021", front: "Artrite psoriásica: 5 padrões articulares?", back: "1) Oligoartrite assimétrica (mais comum, 40%). 2) Poliartrite simétrica (AR-like). 3) IFD + onicolise. 4) Artrite mutilante (pencil-in-cup). 5) Espondilite axial. Dactilite: patognomônica de espondiloartropatia.", category: "reumatologia", tags: ["APs", "dactilite", "padrões"] },
  { id: "reuma-022", front: "PMR vs miosite: como diferenciar?", back: "PMR: dor e rigidez proximal + CPK NORMAL + VHS/PCR muito elevados + sem fraqueza real. Resposta dramática a prednisona 15mg em 24-48h = quase diagnóstico. Miosite: fraqueza real + CPK muito elevada + biópsia confirma.", category: "reumatologia", tags: ["PMR", "miosite", "CPK"] },
  { id: "reuma-023", front: "HAP na esclerodermia: rastreio e tratamento?", back: "Eco Doppler anual. PAP > 40mmHg: cateterismo direito. Tratamento: anti-endotelina (bosentana) ± PDE5i ± análogo de prostaciclina (combinação nas formas graves). TAPSE < 1,7: mau prognóstico.", category: "reumatologia", tags: ["HAP", "esclerodermia", "bosentana"] },
  { id: "reuma-024", front: "Ácido zoledrônico IV: quando indicar em osteoporose?", back: "Intolerância oral, malabsorção (DII, bariátrica), não aderência. Dose: 5mg IV anual × 3 anos. Pré-dose: hidratação + paracetamol (febre e mialgia). Monitorar Ca²⁺ e creatinina.", category: "reumatologia", tags: ["ácido zoledrônico", "osteoporose", "IV"] },
  { id: "reuma-025", front: "Raynaud: quando investigar causa secundária?", back: "Red flags: > 40 anos, assimétrico, ulceração digital, anticorpos positivos, capilaroscopia com megalocapilares + dropout. Causa mais comum: esclerodermia. Capilaroscopia = exame-chave.", category: "reumatologia", tags: ["Raynaud", "secundário", "capilaroscopia"] },
  { id: "reuma-026", front: "Behçet: critérios e manifestações graves?", back: "Úlceras orais recorrentes (obrigatório) + ≥ 2 de: úlceras genitais, uveíte, lesões cutâneas, patergia+. Graves: trombose venosa (veia cava + seios durais), aneurisma arterial pulmonar. Colchicina: artrite + úlceras.", category: "reumatologia", tags: ["Behçet", "patergia", "trombose"] },
  { id: "reuma-027", front: "PAN (poliarterite nodosa): diagnóstico padrão-ouro?", back: "Vasculite necrosante de médios vasos sem ANCA. Biópsia do órgão afetado (nervo, músculo, pele) OU arteriografia (microaneurismas renais/mesentéricos). Associada a HBV. Tratamento: corticoide ± ciclofosfamida + antiviral se HBV+.", category: "reumatologia", tags: ["PAN", "arteriografia", "HBV"] },
  { id: "reuma-028", front: "MCTD: anticorpo e principal causa de morte?", back: "Anti-U1RNP em altos títulos (> 1:160). Overlap de LES + esclerodermia + miosite. HAP: principal causa de morte. Raynaud em 90%. Prognóstico melhor que esclerodermia pura.", category: "reumatologia", tags: ["MCTD", "anti-U1RNP", "HAP"] },
  { id: "reuma-029", front: "Inibidores de JAK na AR: indicação e risco principal?", back: "Falha a ≥ 1 DMARD convencional. Mecanismo: bloqueio de JAK1-2 → inibe IL-6, IL-2, IFN. Risco principal: herpes-zóster (vacinar antes) + tromboembolismo (baricitinibe: alerta FDA em > 65 anos com risco CV).", category: "reumatologia", tags: ["JAK inibidores", "AR", "herpes-zóster"] },
  { id: "reuma-030", front: "Fibromialgia: critérios ACR 2010 e por que abandona os tender points?", back: "WPI ≥ 7 + SSS ≥ 5 (ou WPI 4-6 + SSS ≥ 9) × ≥ 3 meses. Tender points: baixa reprodutibilidade entre avaliadores + não capturam fadiga/sono/cognição. Critérios atuais: mais abrangentes e validados.", category: "reumatologia", tags: ["fibromialgia", "ACR 2010", "WPI"] },
  { id: "reuma-031", front: "AOSD (Still do adulto): tríade e ferritina?", back: "Febre em pico diário + rash salmon evanescente + artrite. Ferritina muito elevada (> 5× LSN, frequentemente > 10.000). Diagnóstico de exclusão. Tto: AINE → corticoide → anakinra (anti-IL1) ou tocilizumabe.", category: "reumatologia", tags: ["AOSD", "ferritina", "rash salmon"] },
  { id: "reuma-032", front: "Corticoide crônico: medidas preventivas obrigatórias?", back: "Cálcio 1000-1200mg + VitD 800-1000UI desde o início. Bifosfonato se ≥ 7,5mg/dia × ≥ 3 meses. IBP se AINE concomitante. Triagem de DM e TB latente. Vacinas inativas antes.", category: "reumatologia", tags: ["corticoide", "prevenção", "osteoporose"] },
  { id: "reuma-033", front: "SAF: qual DOAC contraindicado e por quê?", back: "Rivaroxabana: estudos TRAPS e RAPS = maior trombose em SAF triple positivity vs varfarina. CONTRAINDICADO em SAF de alto risco. Varfarina INR 2-3: padrão-ouro.", category: "reumatologia", tags: ["SAF", "rivaroxabana", "varfarina"] },
  { id: "reuma-034", front: "Síndrome de Felty: tríade e complicações?", back: "AR soropositiva de longa data + esplenomegalia + neutropenia. Risco: infecções graves + linfoma. MTX: melhora neutropenia. Esplenectomia: refratário grave.", category: "reumatologia", tags: ["Felty", "neutropenia", "linfoma"] },
  { id: "reuma-035", front: "Gota: como confirmar o diagnóstico com certeza?", back: "Artrocentese: cristais de MSU (monourato de sódio) em forma de agulha, birrefringência negativa forte. Confirma o diagnóstico. DECT (dupla energia TC): visualiza depósitos de urato in vivo. Ambos superiores ao critério clínico + uricemia.", category: "reumatologia", tags: ["gota", "MSU", "artrocentese"] },
  { id: "reuma-036", front: "Miopatia por estatina: quando é rabdomiólise?", back: "CPK > 40× LSN + mioglobinúria + IRA = rabdomiólise. Emergência: hidratação IV agressiva + suspender estatina. Interações de risco: fibratos (genfibrozila), ciclosporina, azólicos.", category: "reumatologia", tags: ["estatina", "rabdomiólise", "CPK"] },
  { id: "reuma-037", front: "Doença de Paget ósseo: achados e tratamento?", back: "FA muito elevada + Ca²⁺/P normais. RX: algodão no crânio + tíbia em sabre. Complicação: surdez (VIII par comprimido). Tratamento: ácido zoledrônico 5mg IV dose única (remissão prolongada).", category: "reumatologia", tags: ["Paget", "FA", "ácido zoledrônico"] },
  { id: "reuma-038", front: "LES refratário a HCQ + corticoide: próximas opções?", back: "MTX (artrite, pele), azatioprina, MMF (renal). Biológicos: belimumabe (anti-BLYS, reduz flares + preserva renal), anifrolumabe (anti-IFN tipo I). Rituximabe: off-label para refratário grave.", category: "reumatologia", tags: ["LES refratário", "belimumabe", "anifrolumabe"] },
  { id: "reuma-039", front: "HADD (deposição de hidroxiapatita): onde deposita e tratamento?", back: "Tendão supraespinhoso (mais comum) → periartrite do ombro aguda. RX: calcificação em nuvem/pó. Tto: AINE + corticoide local + barbotagem. Cirurgia artroscópica: refratário.", category: "reumatologia", tags: ["HADD", "hidroxiapatita", "ombro"] },
  { id: "reuma-040", front: "Síndrome de hipermobilidade: escore de Beighton?", back: "9 pontos: pinky > 90° (1 cada mão), polegar ao antebraço (1 cada), cotovelo > 0° (1 cada), joelho > 0° (1 cada), palmas no chão joelhos estendidos (1). ≥ 5/9 = hipermóvel.", category: "reumatologia", tags: ["hipermobilidade", "Beighton", "hEDS"] },
  { id: "reuma-041", front: "Síndrome de Sneddon: achados?", back: "Trombose arterial cerebral recorrente + livedo reticularis extenso. SAF em 50%. Mulher jovem + AVC + livedo persistente. Biópsia: trombo arterial intraluminal. Anticoagulação: varfarina INR 2-3.", category: "reumatologia", tags: ["Sneddon", "livedo", "SAF"] },
  { id: "reuma-042", front: "DRESS em reumatologia: fármacos mais comuns?", back: "Alopurinol (causa mais comum global), sulfassalazina, leflunomida, HCQ (raro). Latência 2-8 semanas. Suspender imediatamente + corticoide sistêmico. Mortalidade 10% sem tratamento.", category: "reumatologia", tags: ["DRESS", "alopurinol", "sulfassalazina"] },
  { id: "reuma-043", front: "Henoch-Schönlein (IgA-vasculite): adulto vs criança?", back: "Tríade: púrpura não trombocitopênica (MMII) + artrite + dor abdominal ± nefrite. Depósitos de IgA nos vasos. Criança: autolimitada em 90%. Adulto: nefrite mais grave (30% IRC), imunossupressor se proteinúria > 0,5g/dia.", category: "reumatologia", tags: ["IgA vasculite", "adulto", "nefrite"] },
  { id: "reuma-044", front: "Principal causa de morte em AR?", back: "Doença cardiovascular (IAM, AVC): risco 1,5-2× vs população geral. Inflamação sistêmica crônica → aterosclerose acelerada. MTX e HCQ têm efeito cardioprotetor. Meta LDL < 100mg/dL em AR de alto risco.", category: "reumatologia", tags: ["AR", "cardiovascular", "mortalidade"] },
  { id: "reuma-045", front: "Artrocentese: o que o líquido articular revela?", back: "PMN > 50.000: séptico (urgência). 20-50.000: inflamatório (cristais, AR). < 2.000: não inflamatório (OA, traumático). Cristais: MSU (agulha, birrefringência negativa = gota) vs CPPD (retangular, positiva = pseudo-gota).", category: "reumatologia", tags: ["artrocentese", "líquido sinovial", "PMN"] },
  { id: "reuma-046", front: "Artrite reativa pós-estreptocócica: diferença de febre reumática?", back: "AREPo: não migratória, aditiva, pode ter envolvimento axial, sem resposta excelente ao AAS. FR: migratória + ótima resposta ao AAS. AREPo: sem cardite (diagnóstico de exclusão). Eco por 1 ano.", category: "reumatologia", tags: ["artrite reativa", "estreptococo", "febre reumática"] },
  { id: "reuma-047", front: "Abatacepte: quando preferir ao anti-TNF na AR?", back: "DM concomitante (melhor perfil glicêmico), DPOC grave (anti-TNF aumenta infecções respiratórias), FR+/anti-CCP+ (melhor resposta). Mecanismo: bloqueia co-estimulação T (CD80/86 → CD28).", category: "reumatologia", tags: ["abatacepte", "co-estimulação", "AR"] },
  { id: "reuma-048", front: "Profilaxia de Pneumocystis jirovecii (PJP): indicações em reumatologia?", back: "Prednisona ≥ 20mg/dia × > 1 mês + outro imunossupressor, ciclofosfamida IV, CD4 < 200. TMP-SMX 1 cp simples/dia ou 3×/semana. Alternativa: pentamidina inalatória ou dapsona.", category: "reumatologia", tags: ["PJP", "profilaxia", "TMP-SMX"] },
  { id: "reuma-049", front: "Rituximabe na AR: quando indicar e monitoramento?", back: "Falha a anti-TNF ou contraindicação (linfoma prévio, TB irratável, IC grave). Dose: 2 × 1g IV. Monitorar: imunoglobulinas (hipogamaglobulinemia → infecções graves). Vacinas vivas: contraindicadas.", category: "reumatologia", tags: ["rituximabe", "AR", "hipogamaglobulinemia"] },
  { id: "reuma-050", front: "Doença de Gaucher: manifestações ósseas?", back: "Deficiência de glicocerebrosidase: células de Gaucher infiltram osso → crises álgicas ósseas (simulam artrite), necrose avascular (quadril/joelho), infartos ósseos, fraturas patológicas. Tto: terapia de reposição enzimática (imiglicerase).", category: "reumatologia", tags: ["Gaucher", "necrose avascular", "osso"] },
  { id: "reuma-051", front: "Lúpus neuropsiquiátrico: manifestações e avaliação?", back: "Cefaleia (inespecífica), psicose lúpica (específica), convulsões, AVC (SAF associado), mielopatia, neuropatia periférica. RM crânio + LCR (excluir infecção) + angiografia se AVC. Tto: SAF = anticoagulação; inflamação = corticoide + ciclofosfamida.", category: "reumatologia", tags: ["lúpus neuropsiquiátrico", "psicose", "SAF"] },
  { id: "reuma-052", front: "Espondilite anquilosante: quando indicar biológico?", back: "Falha a ≥ 2 AINEs em doses plenas × ≥ 4 semanas cada. 1ª linha: anti-TNF (adalimumabe, golimumabe, etanercepte) ou anti-IL17 (secuquinumabe, ixequizumabe). Anti-IL17: melhor no axial puro. Anti-TNF: melhor se DII concomitante.", category: "reumatologia", tags: ["EA", "anti-IL17", "biológico"] },
  { id: "reuma-053", front: "Nefrite lúpica classe III vs IV: diferença?", back: "Classe III: < 50% dos glomérulos com lesão proliferativa. Classe IV: ≥ 50%. Ambas causam síndrome nefrítica. Classe IV: mais grave + maior risco de IRC. Tratamento igual: MMF ou ciclofosfamida + metilprednisolona.", category: "reumatologia", tags: ["nefrite lúpica", "III", "IV"] },
  { id: "reuma-054", front: "Vasculite leucocitoclástica cutânea: causas e apresentação?", back: "Inflamação de pequenos vasos dérmicos. Púrpura palpável nos MMII. Causas: fármaco (mais comum), infecção (SBGA, HCV), LES, crioglobulinemia. Investigar: FAN, ANCA, crioglobulinas, complemento. Biópsia confirma.", category: "reumatologia", tags: ["vasculite cutânea", "púrpura palpável", "leucocitoclástica"] },
  { id: "reuma-055", front: "SLEDAI: o que mede e pontuação?", back: "SLEDAI-2K: 24 descritores clínicos/laboratoriais. 0 = remissão. 1-5 = leve. 6-10 = moderado. > 10 = alto. Anti-dsDNA crescente + C3↓ + SLEDAI crescente = flare → intensificar tratamento.", category: "reumatologia", tags: ["SLEDAI", "LES", "atividade"] },
  { id: "reuma-056", front: "HLH (hemofagocitose) associada a doenças reumatológicas: diagnóstico?", back: "Febre + esplenomegalia + pancitopenia + hipertrigliceridemia + hipofibrinogenemia + ferritina muito alta (> 500, frequentemente > 10.000). Associada a AOSD, LES, AIJ sistêmica. Critérios HLH-2004: ≥ 5/8. Tto urgente: corticoide + etoposídeo + ciclosporina.", category: "reumatologia", tags: ["HLH", "hemofagocitose", "AOSD"] },
  { id: "reuma-057", front: "DPI na esclerodermia: exame de escolha e tratamento?", back: "TCAR sem contraste: padrão-ouro. Padrão mais comum: NSIP (vidro fosco + bandas subpleurais). Monitorar CVF a cada 3-6 meses. Tto: nintedanibe (aprovado para SSc-DPI) ± micofenolato.", category: "reumatologia", tags: ["DPI", "esclerodermia", "nintedanibe"] },
  { id: "reuma-058", front: "Artrite séptica gonocócica vs não-gonocócica?", back: "Gonocócica: jovem sexualmente ativo, tenossinovite migratória + pápulas/vesículas, resposta rápida à ceftriaxona, culturas frequentemente negativas. Não-gonocócica: S. aureus, pus espesso, culturas positivas, urgência cirúrgica.", category: "reumatologia", tags: ["artrite séptica", "gonococo", "S. aureus"] },
  { id: "reuma-059", front: "Vasculite de grandes vasos: como diferenciar Takayasu de ACG?", back: "Takayasu: mulher < 40 anos, aorta + grandes ramos. ACG: > 50 anos, artéria temporal + aorta. HLA-B52 (Takayasu) vs HLA-DRB1 (ACG). Amaurose: urgência em ACG. Biópsia temporal: padrão-ouro ACG.", category: "reumatologia", tags: ["Takayasu", "ACG", "grandes vasos"] },
  { id: "reuma-060", front: "Rituximabe no tratamento de vasculite ANCA+: manutenção?", back: "Manutenção: 500mg IV a cada 6 meses × 2 anos (MAINRITSAN2: superior à azatioprina). Duração total: ≥ 2 anos. Monitorar ANCA periodicamente. Suspensão precoce: alto risco de recorrência.", category: "reumatologia", tags: ["vasculite ANCA", "rituximabe", "MAINRITSAN"] },
  { id: "reuma-061", front: "Osteoporose: quando usar denosumabe em vez de bifosfonato?", back: "DRC com TFG < 30 (bifosfonato contraindicado), intolerância ao bifosfonato, malabsorção GI grave, resposta insuficiente. Dose: 60mg SC a cada 6 meses. NUNCA suspender abruptamente (rebote com múltiplas fraturas vertebrais).", category: "reumatologia", tags: ["denosumabe", "osteoporose", "DRC"] },
  { id: "reuma-062", front: "Rigidez matinal na AR: mecanismo e diagnóstico diferencial?", back: "Rigidez > 1h: inflamação sinovial (IL-6 + TNF picos noturnos + acúmulo de líquido sem movimento). OA: rigidez < 30 min (gel phenomenon). Mensurar duração para avaliar atividade da AR. Quanto mais ativo, mais prolongada.", category: "reumatologia", tags: ["rigidez matinal", "AR", "OA"] },
  { id: "reuma-063", front: "Lúpus drug-induced: fármacos mais comuns e diferença do LES idiopático?", back: "Hidralazina, procainamida, isoniazida, metildopa, anti-TNF. Anticorpo: anti-histona (> 95%). Sem nefrite/SNC, complemento normal, anti-dsDNA negativo. Reversível ao suspender o fármaco.", category: "reumatologia", tags: ["lupus drug-induced", "anti-histona", "hidralazina"] },
  { id: "reuma-064", front: "Qual o papel dos anti-IL6 (tocilizumabe, sarilumabe) na AR?", back: "Falha a ≥ 1 DMARD convencional. Bloqueiam receptor de IL-6. Vantagem: podem ser usados em monoterapia (sem MTX). Excelentes para AOSD. Riscos: diverticulite, infecções, LDL elevado, transaminases, neutropenia.", category: "reumatologia", tags: ["anti-IL6", "tocilizumabe", "AR"] },
  { id: "reuma-065", front: "Fibromialgia: por que AINEs e opioides são ineficazes?", back: "Sensibilização central: amplificação dos sinais dolorosos no SNC sem inflamação periférica real. AINEs: atuam perifericamente. Opioides: pioram a sensibilização (hiperalgesia induzida + dependência). Eficazes: duloxetina, pregabalina, amitriptilina, exercício aeróbico, TCC.", category: "reumatologia", tags: ["fibromialgia", "sensibilização central", "AINE"] },
  { id: "reuma-066", front: "Anti-dsDNA no LES: por que monitorar?", back: "Correlaciona com atividade da doença, especialmente nefrite. Sobe nos flares. Anti-dsDNA crescente + C3↓ = início de flare → intensificar tratamento. Monitorar junto com C3/C4 a cada 3-6 meses.", category: "reumatologia", tags: ["anti-dsDNA", "LES", "monitoramento"] },
  { id: "reuma-067", front: "Vacinas no imunossuprimido: quais são seguras?", back: "Seguras: influenza anual, pneumococo (PCV13 + PPSV23), HepA, HepB, Tdap, HPV, meningocócica. Contraindicadas com imunossupressor: BCG, varicela, MMR, febre amarela. Vacinar antes do início do imunossupressor quando possível.", category: "reumatologia", tags: ["vacinação", "imunossuprimido", "vacinas vivas"] },
  { id: "reuma-068", front: "Síndrome de Raynaud: fisiopatologia e classificação?", back: "Vasoespasmo reversível de pequenas artérias digitais. Trifásica: brancura (espasmo) → cianose (desoxigenação) → eritema (reperfusão). Primário: < 40 anos, simétrico, benigno. Secundário: causa identificável, assimétrico, úlceras.", category: "reumatologia", tags: ["Raynaud", "vasoespasmo", "trifásica"] },
  { id: "reuma-069", front: "Crioglobulinemia: tipos e causas?", back: "Tipo I (monoclonal): mieloma, Waldenström → hiperviscosidade. Tipo II (mista, FR IgM mono + IgG poli): HCV em 80%. Tipo III (mista policlonal): autoimune, infecções crônicas. Tipos II-III: púrpura + artralgia + GN + neuropatia. C4 baixo característico.", category: "reumatologia", tags: ["crioglobulinemia", "HCV", "tipos"] },
  { id: "reuma-070", front: "LES e gestação: medicamentos seguros e contraindicados?", back: "Seguros: HCQ (manter), azatioprina, prednisona baixa dose. Suspender: MTX (3 meses antes), MMF (3 meses antes), ciclofosfamida, leflunomida. SAF: HBPM + AAS se anticorpos positivos.", category: "reumatologia", tags: ["LES", "gestação", "HCQ"] },
  { id: "reuma-071", front: "DM amiopática (CADM): anticorpo e risco especial?", back: "Anti-MDA5 positivo. DPI rapidamente progressiva (alta mortalidade, refratária). Tratamento agressivo precoce: corticoide + tacrolimus + ciclofosfamida. Prognóstico reservado mesmo com tratamento.", category: "reumatologia", tags: ["DM amiopática", "anti-MDA5", "DPI"] },
  { id: "reuma-072", front: "Qual o risco de infecção com biológicos em reumatologia?", back: "Anti-TNF: TB + histoplasmose + infecções bacterianas graves. Rituximabe: hipogamaglobulinemia → encapsulados (pneumococo). Abatacepte: respiratórias. JAK: herpes-zóster (mais frequente). Triagem universal: TB, HBV, HIV, vacinas.", category: "reumatologia", tags: ["biológicos", "infecção", "triagem"] },
  { id: "reuma-073", front: "Artrite psoriásica: qual o escore de atividade específico?", back: "DAPSA (Disease Activity in PSoriatic Arthritis): contagem articular + proteínas reativas + EVA dor e atividade global. BASDAI: para componente axial. PsAID: impacto na vida do paciente. GRAPPA 2022: avalia domínios separadamente.", category: "reumatologia", tags: ["APs", "DAPSA", "escore de atividade"] },
  { id: "reuma-074", front: "Lúpus cutâneo subagudo (LECS): anticorpo e tratamento?", back: "Anti-Ro/SS-A+ em 70-80%. Lesões papuloescamosas ou anulares fotossensíveis. Tratamento: proteção solar + HCQ 1ª linha. Refratário: retinoides, dapsona, talidomida. Se induzido por fármaco: suspender o causador.", category: "reumatologia", tags: ["LECS", "anti-Ro", "HCQ"] },
  { id: "reuma-075", front: "Por que MTX causa mucosite e como prevenir?", back: "MTX inibe DHFR → bloqueio de folato → mucosite + hepatotoxicidade. Prevenção: folato 5mg/semana (reduz toxicidade sem reduzir eficácia). Álcool: contraindicado (hepatotoxicidade sinérgica).", category: "reumatologia", tags: ["MTX", "folato", "mucosite"] },
  { id: "reuma-076", front: "Osteoporose induzida por corticoide: dose mínima de risco?", back: "Prednisona ≥ 7,5mg/dia por ≥ 3 meses: risco significativo. Fraturas ocorrem mesmo com DEXA > -2,5 (T-score não reflete o risco real na OIC). Prevenção: cálcio + VitD + bifosfonato desde o início do corticoide de alto risco.", category: "reumatologia", tags: ["OIC", "corticoide", "bifosfonato"] },
  { id: "reuma-077", front: "Síndrome de sobreposição mais comum em reumatologia?", back: "MCTD (Sharp): anti-U1RNP + LES + esclerodermia + miosite. Escleromiosite: anti-PM/Scl. LES + Sjögren: anti-Ro+La. Qualquer combinação com características de ≥ 2 doenças do tecido conjuntivo.", category: "reumatologia", tags: ["overlap", "MCTD", "U1RNP"] },
  { id: "reuma-078", front: "Livedo reticularis: quando é patológico?", back: "Benigno: fino, simétrico, reversível ao aquecimento. Patológico: extenso, irregular, persistente + outros sinais. Causas: SAF (trombose + abortos), LES, crioglobulinemia, PAN, Sneddon (AVC + livedo). Investigar: FAN, ANCA, anticorpos antifosfolipídios.", category: "reumatologia", tags: ["livedo reticularis", "SAF", "patológico"] },
  { id: "reuma-079", front: "Síndrome de Sjögren: teste de Schirmer e Rosa Bengala?", back: "Schirmer: < 5mm em 5 min = xeroftalmia objetiva. Rosa Bengala/verde de lisamina: cora células epiteliais mortas da conjuntiva/córnea = queratoconjuntivite sicca. Biópsia de glândula salivar menor: foco score ≥ 1 = padrão-ouro histológico.", category: "reumatologia", tags: ["Sjögren", "Schirmer", "Rosa Bengala"] },
  { id: "reuma-080", front: "Qual a diferença entre BASDAI e ASDAS na EA?", back: "BASDAI: 6 perguntas auto-aplicadas (0-10). ≥ 4 = alta atividade. Subjetivo. ASDAS: BASDAI + PCR ou VHS. Objetivo. < 1,3 = remissão. > 3,5 = muito alto. ASDAS guia melhor as decisões terapêuticas.", category: "reumatologia", tags: ["BASDAI", "ASDAS", "EA"] },
  { id: "reuma-081", front: "Artrite da hepatite C: como manejar?", back: "Artralgia/artrite não erosiva + crioglobulinemia mista tipo II. FR pode ser + (crioglobulinemia). Anti-CCP: negativo (diferencia de AR). Tratamento HCV com DAAs: resolve crioglobulinemia em 70-80%. Anti-TNF: contraindicado em HCV ativo não tratado.", category: "reumatologia", tags: ["HCV", "artrite", "crioglobulinemia"] },
  { id: "reuma-082", front: "Olecranona articulação de Charcot: causa reumatológica mais comum?", back: "Artropatia neuropática (Charcot): destruição articular por perda de sensação protetora. Causa mais comum: DM (Charcot do pé/tornozelo). Outras: siringomielia (Charcot do ombro), tabes dorsalis (quadril). Radiologia: destruição + esclerose + deformidade (3D). Tto: imobilização + descarga.", category: "reumatologia", tags: ["Charcot", "artropatia neuropática", "DM"] },
  { id: "reuma-083", front: "Uso de bifosfonatos: quando suspender e risco de ONM?", back: "ONM (osteonecrosis of mandible): risco aumenta com duração > 5 anos + corticoide + extração dentária + quimioterapia. Suspender 3 meses antes de cirurgia oral invasiva (drug holiday controverso). Dentista obrigatório antes de iniciar bifosfonato IV.", category: "reumatologia", tags: ["bifosfonato", "ONM", "osteonecrosis"] },
  { id: "reuma-084", front: "Síndrome de Sjögren primária vs secundária?", back: "Primária: Sjögren isolado, anti-Ro/La+ mais frequente, linfoma principalmente no primário. Secundária: Sjögren associado a AR, LES, esclerodermia, etc. Manifestações extraglandulares mais comuns no primário.", category: "reumatologia", tags: ["Sjögren", "primário", "secundário"] },
  { id: "reuma-085", front: "Qual a TCAR mais sugestiva de NSIP vs UIP na DPI?", back: "NSIP (Non-Specific Interstitial Pneumonia): vidro fosco bilateral simétrico + bandas subpleurais + sem faveolamento. UIP (Usual Interstitial Pneumonia): faveolamento + trações bronquiectásicas + distribuição em bases e subpleural. UIP = FPI. NSIP = esclerodermia, PM/DM, Sjögren.", category: "reumatologia", tags: ["TCAR", "NSIP", "UIP"] },
  { id: "reuma-086", front: "Raynaud ulcerado na esclerodermia: escalonamento terapêutico?", back: "BCC (anlodipino) → sildenafila → bosentana (previne novas úlceras, não cura existentes) → iloprost IV (análogo de prostaciclina × 3-5 dias: ciclos para úlceras ativas) → simpatectomia digital (refratário grave).", category: "reumatologia", tags: ["Raynaud", "úlceras digitais", "iloprost"] },
  { id: "reuma-087", front: "Qual a diferença entre entesite e sinovite?", back: "Sinovite: inflamação da membrana sinovial → calor + edema + dor articular (AR). Entesite: inflamação na inserção de tendão/ligamento no osso → dor palpável em pontos de inserção (calcâneo, joelho, pelve). Específica de espondiloartropatias. US Doppler: detecta entesite subclínica.", category: "reumatologia", tags: ["entesite", "sinovite", "espondiloartropatia"] },
  { id: "reuma-088", front: "Lúpus neonatal: anticorpos e manifestações?", back: "Anti-Ro/SS-A e anti-La/SS-B maternos atravessam a placenta. BAV congênito 3° grau (irreversível, urgência com marca-passo) + rash transitório. Mãe com anti-Ro+: eco fetal semanal nas semanas 18-26.", category: "reumatologia", tags: ["lúpus neonatal", "anti-Ro", "BAV congênito"] },
  { id: "reuma-089", front: "Qual a principal causa de morte na esclerodermia?", back: "dcSSc: DPI (doença pulmonar intersticial). lcSSc: HAP (hipertensão arterial pulmonar). Antigamente: CRE (crise renal) = principal; hoje controlada com IECA.", category: "reumatologia", tags: ["esclerodermia", "DPI", "HAP", "mortalidade"] },
  { id: "reuma-090", front: "Metotexato: por que pode se acumular em anemia megaloblástica?", back: "MTX compete com folato para a DHFR. Com suplementação insuficiente de folato + DRC (acúmulo de MTX) → macrocitose + anemia megaloblástica. Monitorar VCM + hemograma mensalmente nos primeiros 6 meses.", category: "reumatologia", tags: ["MTX", "megaloblástica", "folato"] },
  { id: "reuma-091", front: "Síndrome de Felty: por que MTX melhora a neutropenia?", back: "MTX reduz a produção de fator estimulador de colônia negativo (IFN-γ, TNF) pelo baço hiperativo. Além do efeito na AR, reduz o sequestro esplênico de neutrófilos → melhora a contagem. Esplenectomia: reservada para casos refratários a MTX.", category: "reumatologia", tags: ["Felty", "MTX", "neutropenia"] },
  { id: "reuma-092", front: "Qual o papel da PCR vs VHS no monitoramento de reumatologia?", back: "PCR: produzida pelo fígado em resposta à IL-6. Sobe em 6-12h, cai rapidamente. Mais específica. VHS: sobe lentamente (24-48h), persiste por semanas. Influenciado por anemia e fibrinogênio. PMR e arterite temporal: VHS mais útil. AR ativa: PCR + VHS complementares.", category: "reumatologia", tags: ["PCR", "VHS", "monitoramento"] },
  { id: "reuma-093", front: "Artrite enteropática na DII: tipos e tratamento?", back: "Tipo 1 (< 5 articulações, grandes, correlaciona com DII): controlar DII + AINE com cautela. Tipo 2 (> 5 articulações, simétrico, independente): MTX ou sulfassalazina. Espondilite axial: anti-TNF (infliximabe: eficácia intestinal + axial). Anti-IL17: pode piorar DII.", category: "reumatologia", tags: ["DII", "artrite enteropática", "anti-TNF"] },
  { id: "reuma-094", front: "Vasculite cutânea por IgA em adulto: quando biopsiar o rim?", back: "Henoch-Schönlein adulto: biópsia renal se proteinúria > 0,5g/dia ou Cr elevada. Achado: depósitos de IgA no mesângio (IgA-vasculite nephritis). Tratamento nefrite grave: prednisona + azatioprina ou rituximabe.", category: "reumatologia", tags: ["IgA vasculite", "biópsia renal", "adulto"] },
  { id: "reuma-095", front: "Capilaroscopia periungueal: o que o padrão escleroderma indica?", back: "Megalocapilares (dilatação > 4×) + dropout (áreas avasculares) + neoformação desorganizada. Progressão: early → active → late (perda crescente). Raynaud + FAN+ + padrão escleroderma: alto risco de desenvolver esclerodermia nos próximos anos.", category: "reumatologia", tags: ["capilaroscopia", "scleroderma pattern", "Raynaud"] },
  { id: "reuma-096", front: "Crioglobulinemia tipo II associada a HCV: tratamento?", back: "DAAs (antivirais diretos): sofosbuvir + velpatasvir × 12 semanas → cura do HCV → resolução da crioglobulinemia em 70-80%. Vasculite grave antes da cura do HCV: rituximabe + corticoide transitório.", category: "reumatologia", tags: ["crioglobulinemia", "HCV", "DAA"] },
  { id: "reuma-097", front: "Qual a diferença entre espondilite anquilosante radiográfica e axSpA não-radiográfica?", back: "Radiográfica (EA): sacroileíte no RX (Nova York modificado, grau II bilateral ou III-IV unilateral). Não-radiográfica (nr-axSpA): HLA-B27+ ou edema na RM das sacroilíacas sem critério radiológico. Resposta ao anti-TNF: semelhante em ambas.", category: "reumatologia", tags: ["axSpA", "EA", "nr-axSpA"] },
  { id: "reuma-098", front: "Qual o risco do abatacepte em paciente com DPOC moderado-grave?", back: "Abatacepte: perfil favorável em DPOC (ao contrário do anti-TNF que aumenta infecções respiratórias em DPOC). Pode ser a opção preferencial de biológico em AR + DPOC moderado-grave.", category: "reumatologia", tags: ["abatacepte", "DPOC", "AR"] },
  { id: "reuma-099", front: "SAPHO: o que é e onde acomete?", back: "Sinovite + Acne + Pustulosa palmoplantar + Hiperostose + Osteíte. Espondiloartropatia. Acometimento esterno-clavicular: osteíte (bull's head na cintilografia). Associada a acne conglobata e hidradenite. Tto: AINE, bifosfonato, anti-TNF.", category: "reumatologia", tags: ["SAPHO", "osteíte", "espondiloartropatia"] },
  { id: "reuma-100", front: "Dermatomiosite: rastreio de malignidade?", back: "Risco 3-8× de CA (mama, ovário, pulmão, colorretal, nasogástrico em asiáticos). Anti-TIF1γ: maior risco de CA em > 40 anos. Rastreio: TC tórax/abdome/pelve + PET-CT se suspeita. Por 3-5 anos após diagnóstico.", category: "reumatologia", tags: ["dermatomiosite", "CA", "anti-TIF1γ"] },
  { id: "reuma-101", front: "Síndrome antifosfolipídio catastrófica (CAPS): precipitantes?", back: "Infecção (mais comum), cirurgia, suspensão da anticoagulação, gravidez, trauma. Mortalidade 50%. Prevenir: manter anticoagulação rigorosa em SAF de alto risco. Triple therapy + tratar o precipitante.", category: "reumatologia", tags: ["CAPS", "precipitantes", "anticoagulação"] },
  { id: "reuma-102", front: "AOSD vs HLH: como diferenciar?", back: "AOSD: ferritina > 5× (frequentemente 1000-5000) + febre + rash + artrite + LEUC normal/elevado. HLH: ferritina > 500 (frequentemente > 10.000) + pancitopenia + hemofagocitose na MO + hipertrigliceridemia + hipofibrinogenemia. AOSD pode causar HLH (MAS: macrophage activation syndrome).", category: "reumatologia", tags: ["AOSD", "HLH", "ferritina"] },
  { id: "reuma-103", front: "Qual a diferença terapêutica entre PMR isolada e PMR associada a ACG?", back: "PMR isolada: prednisona 15-20mg/dia. ACG com/sem amaurose: prednisona 40-60mg/dia. Amaurose: metilprednisolona 500-1000mg IV × 3 dias. Tocilizumabe IV mensal: aprovado para reduzir recaídas em ACG + poupar corticoide.", category: "reumatologia", tags: ["PMR", "ACG", "prednisona"] },
  { id: "reuma-104", front: "Qual o papel da biópsia da artéria temporal na ACG?", back: "Padrão-ouro: inflamação granulomatosa + células gigantes + lesão da lâmina elástica interna. Realizar em < 2 semanas do início do corticoide (corticoide não elimina o achado em 2-4 semanas). Negativa não exclui (skiping lesions): US Doppler das temporais como alternativa.", category: "reumatologia", tags: ["ACG", "biópsia temporal", "células gigantes"] },
  { id: "reuma-105", front: "Espondilite anquilosante: o que é o bamboo spine?", back: "Fusão vertebral progressiva por ossificação dos ligamentos longitudinais anteriores e posteriores + sindesmófitos contíguos (pontes ósseas entre vértebras). RX coluna total: coluna em 'bambu'. Representa doença avançada com mobilidade mínima. Osteoporose associada: risco de fratura vertebral instável.", category: "reumatologia", tags: ["EA", "bamboo spine", "sindesmófito"] },
  { id: "reuma-106", front: "Terapia de reposição enzimática na doença de Fabry: indicação em reumatologia?", back: "Fabry (deficiência de alfa-galactosidase A): crises álgicas (imitam artrite, neuropatia periférica), angioqueratomas, cardiomiopatia, DRC. Diagnóstico: dosagem enzimática + mutação GLA. TRE (agalsidase alfa ou beta): indicada em todos os homens sintomáticos + mulheres com comprometimento de órgão.", category: "reumatologia", tags: ["Fabry", "alfa-galactosidase", "TRE"] },
  { id: "reuma-107", front: "Poliangiíte microscópica: diferença de GPA?", back: "PAM: sem granulomas, sem envolvimento de vias aéreas superiores. Hemorragia alveolar + GNRP. p-ANCA/anti-MPO. GPA: granulomas + vias aéreas superiores + pulmões + rins. c-ANCA/anti-PR3. PAM: menor risco de recidiva que GPA. Tratamento: idêntico.", category: "reumatologia", tags: ["PAM", "GPA", "anti-MPO"] },
  { id: "reuma-108", front: "Qual o anticorpo que prediz crise renal esclerodérmica?", back: "Anti-RNA polimerase III: presente em 25% da dcSSc. Fortemente associado à CRE (RR > 10×). Risco: 20-25% dos pacientes anti-RNA pol III+ desenvolvem CRE. Rastrear PA semanalmente nos primeiros 4 anos de doença neste subgrupo.", category: "reumatologia", tags: ["CRE", "anti-RNA pol III", "rastreio"] },
  { id: "reuma-109", front: "Por que não usar bifosfonato oral em paciente com bariátrica?", back: "Malabsorção pós-bypass gástrico: bifosfonato oral não absorvido adequadamente. Alternativas: ácido zoledrônico IV anual ou denosumabe SC semestral. Monitorar VitD (frequentemente deficiente após bariátrica) + Ca²⁺.", category: "reumatologia", tags: ["bifosfonato", "bariátrica", "malabsorção"] },
  { id: "reuma-110", front: "Síndrome de Sjogren: quando indicar pilocarpina?", back: "Xerostomia sintomática sem resposta a medidas locais (higiene oral + saliva artificial + hidratação). Pilocarpina 5mg 3-4×/dia: estimula a secreção residual. Contraindicada: glaucoma de ângulo fechado, asma, IC grave. Alternativa: cevimelina.", category: "reumatologia", tags: ["Sjögren", "pilocarpina", "xerostomia"] },
  { id: "reuma-111", front: "Qual o papel do ácido úrico no manejo da gota além de hipouricemiante?", back: "Urato sérico guia: ajuste de dose do alopurinol (meta < 6mg/dL ou < 5mg/dL se tofos), avaliação da aderência ao tratamento, predição de risco cardiovascular (hiperuricemia como fator de risco). Monitorar a cada 2-4 semanas no início, depois trimestral quando na meta.", category: "reumatologia", tags: ["gota", "ácido úrico", "monitoramento"] },
  { id: "reuma-112", front: "Artrite por cristais de pirofosfato: investigar que causas secundárias?", back: "CPPD secundário: hiperparatireoidismo (PTH), hemocromatose (ferro + ferritina), hipomagnesemia (Mg), hipotireoidismo (TSH), hemodiálise, hipofosfatasia. Investigar em paciente jovem ou com forma grave/atípica.", category: "reumatologia", tags: ["CPPD", "causas secundárias", "hiperparatireoidismo"] },
  { id: "reuma-113", front: "Quando usar metilprednisolona em pulso vs prednisona oral em reumatologia?", back: "Pulso IV (500-1000mg/dia × 3 dias): nefrite lúpica grave, vasculite com hemorragia alveolar, miosite grave com disfunção respiratória, ACG com amaurose. Prednisona oral: doenças de atividade moderada, manutenção. Pulso: efeito mais rápido e poupador de dose total.", category: "reumatologia", tags: ["metilprednisolona", "pulso", "indicações"] },
  { id: "reuma-114", front: "Como interpretar FAN positivo em baixo título (1:80)?", back: "FAN 1:80 em painel IFI: sensível para LES mas inespecífico. Positivo em: população geral (até 5% em títulos baixos), idosos, doenças tireoidianas, hepatite C, parentes de pacientes com LES. Necessário contexto clínico + anticorpos específicos (anti-Sm, anti-dsDNA, anti-Ro). FAN isolado NÃO fecha diagnóstico de LES.", category: "reumatologia", tags: ["FAN", "interpretação", "LES"] },
  { id: "reuma-115", front: "Qual o risco do suspender abruptamente o denosumabe?", back: "Rebote: múltiplas fraturas vertebrais por supressão prévia do turnover ósseo. Rebound de osteoclastos quando denosumabe é retirado. Prevenir: substituir por bifosfonato (ácido zoledrônico 1 dose) imediatamente após a última dose de denosumabe (6 meses após). Nunca suspender sem transição.", category: "reumatologia", tags: ["denosumabe", "rebote", "bifosfonato"] },
  { id: "reuma-116", front: "Qual o critério diagnóstico de SHM/MAS (macrophage activation syndrome)?", back: "MAS em reumatologia (principalmente AIJ sistêmica e LES): ferritina > 684 + qualquer 2 de: plaquetas < 181.000, AST > 48, triglicérides > 156, fibrinogênio < 360. Critérios de Ravelli 2016. Tto urgente: corticoide IV + ciclosporina ± anakinra.", category: "reumatologia", tags: ["MAS", "hemofagocitose", "AIJ sistêmica"] },
];
